// Shuffle once per visit to the feed, avoiding consecutive repeat openers.
let previousReel;
try { previousReel=sessionStorage.getItem('dd_reels_first'); } catch (_) {}
function shuffleReels(){
  const reels=window.REELS;
  if(reels.length<2)return;
  const starters=reels.filter(r=>r.id!==previousReel);
  const first=starters[Math.floor(Math.random()*starters.length)];
  const rest=reels.filter(r=>r!==first);
  for(let i=rest.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [rest[i],rest[j]]=[rest[j],rest[i]]; }
  reels.splice(0,reels.length,first,...rest);
  previousReel=first.id;
  try { sessionStorage.setItem('dd_reels_first',previousReel); } catch (_) {}
}
